@layer components {
  /* Attachment */

  [data-slot="attachment"] {
    background: var(--vh-bg);
    border: 1px solid var(--vh-border);
    border-radius: calc(var(--vh-radius) * 1.5);
    color: var(--vh-text);
    display: flex;
    flex-shrink: 0;
    flex-wrap: wrap;
    max-width: 100%;
    min-width: 0;
    position: relative;
    transition: background-color 150ms, border-color 150ms;
    width: fit-content;
  }

  [data-slot="attachment"]:has(> a, > button):hover {
    background: color-mix(in oklab, var(--vh-bg-elevated) 50%, var(--vh-bg));
  }

  [data-slot="attachment"][data-status="error"] {
    border-color: color-mix(in oklab, var(--vh-error) 30%, transparent);
  }

  [data-slot="attachment"][data-status="idle"] {
    border-style: dashed;
  }

  [data-slot="attachment"][data-size="md"] {
    font-size: 0.875rem;
    gap: 0.5rem;
    line-height: 1.25rem;
  }

  [data-slot="attachment"][data-size="md"]:has([data-slot="attachment-media"]) {
    padding: 0.5rem;
  }

  [data-slot="attachment"][data-size="md"]:has([data-slot="attachment-content"]) {
    padding: 0.5rem 0.625rem;
  }

  [data-slot="attachment"][data-size="sm"] {
    font-size: 0.75rem;
    gap: 0.625rem;
    line-height: 1rem;
  }

  [data-slot="attachment"][data-size="sm"]:has([data-slot="attachment-media"]) {
    padding: 0.375rem;
  }

  [data-slot="attachment"][data-size="sm"]:has([data-slot="attachment-content"]) {
    padding: 0.375rem 0.5rem;
  }

  [data-slot="attachment"][data-size="xs"] {
    border-radius: var(--vh-radius);
    font-size: 0.75rem;
    gap: 0.375rem;
    line-height: 1rem;
  }

  [data-slot="attachment"][data-size="xs"]:has([data-slot="attachment-media"]) {
    padding: 0.25rem;
  }

  [data-slot="attachment"][data-size="xs"]:has([data-slot="attachment-content"]) {
    padding: 0.25rem 0.375rem;
  }

  [data-slot="attachment"][data-orientation="horizontal"] {
    align-items: center;
    min-width: 10rem;
  }

  [data-slot="attachment"][data-orientation="vertical"] {
    flex-direction: column;
    width: 6rem;
  }

  [data-slot="attachment"][data-orientation="vertical"]:has([data-slot="attachment-content"]) {
    width: 7.5rem;
  }

  [data-slot="attachment-media"] {
    align-items: center;
    aspect-ratio: 1;
    background: var(--vh-bg-elevated);
    border-radius: var(--vh-radius);
    color: var(--vh-highlighted);
    display: flex;
    flex-shrink: 0;
    justify-content: center;
    overflow: hidden;
    position: relative;
    width: 2.5rem;
  }

  [data-slot="attachment"][data-orientation="vertical"] [data-slot="attachment-media"] {
    width: 100%;
  }

  [data-slot="attachment"][data-size="sm"] [data-slot="attachment-media"] {
    width: 2rem;
  }

  [data-slot="attachment"][data-size="xs"] [data-slot="attachment-media"] {
    border-radius: calc(var(--vh-radius) * 0.75);
    width: 1.75rem;
  }

  [data-slot="attachment"][data-status="error"] [data-slot="attachment-media"] {
    background: color-mix(in oklab, var(--vh-error) 10%, transparent);
    color: var(--vh-error);
  }

  [data-slot="attachment-media"] svg {
    pointer-events: none;
  }

  [data-slot="attachment-media"] :is(svg, .iconify):not([class*="size-"]) {
    height: 1rem;
    width: 1rem;
  }

  [data-slot="attachment"][data-orientation="vertical"] [data-slot="attachment-media"] :is(svg, .iconify):not([class*="size-"]) {
    height: 1.5rem;
    width: 1.5rem;
  }

  [data-slot="attachment"][data-size="xs"] [data-slot="attachment-media"] :is(svg, .iconify):not([class*="size-"]) {
    height: 0.875rem;
    width: 0.875rem;
  }

  [data-slot="attachment-media"][data-kind="image"] {
    opacity: 0.6;
  }

  [data-slot="attachment"]:is([data-status="done"], [data-status="idle"]) [data-slot="attachment-media"][data-kind="image"] {
    opacity: 1;
  }

  [data-slot="attachment-media"][data-kind="image"] > img {
    aspect-ratio: 1;
    object-fit: cover;
    width: 100%;
  }

  [data-slot="attachment-content"] {
    flex: 1;
    line-height: 1.25;
    max-width: 100%;
    min-width: 0;
  }

  [data-slot="attachment"][data-orientation="vertical"] [data-slot="attachment-content"] {
    padding-inline: 0.25rem;
  }

  [data-slot="attachment-title"] {
    display: block;
    font-weight: 500;
    max-width: 100%;
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  [data-slot="attachment-description"] {
    color: var(--vh-muted);
    display: block;
    font-size: 0.75rem;
    line-height: 1rem;
    margin-top: 0.125rem;
    max-width: 100%;
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  [data-slot="attachment"][data-status="error"] [data-slot="attachment-description"] {
    color: color-mix(in oklab, var(--vh-error) 80%, transparent);
  }

  [data-slot="attachment-actions"] {
    align-items: center;
    display: flex;
    flex-shrink: 0;
    position: relative;
    z-index: 20;
  }

  [data-slot="attachment"][data-orientation="vertical"] [data-slot="attachment-actions"] {
    gap: 0.25rem;
    position: absolute;
    right: 0.75rem;
    top: 0.75rem;
  }

  /* Remove and other icon buttons: a 24px square with a 16px icon, the look of a small ghost button. */
  [data-slot="attachment-action"] {
    align-items: center;
    background: transparent;
    border: 0;
    border-radius: calc(var(--vh-radius) * 0.75);
    color: var(--vh-text);
    cursor: pointer;
    display: inline-flex;
    flex-shrink: 0;
    justify-content: center;
    padding: 0.25rem;
    transition: color 150ms cubic-bezier(0.4, 0, 0.2, 1), background-color 150ms cubic-bezier(0.4, 0, 0.2, 1);
  }

  [data-slot="attachment-action"] > * {
    flex-shrink: 0;
    height: 1rem;
    width: 1rem;
  }

  @media (hover: hover) {
    [data-slot="attachment-action"]:hover:not(:disabled) {
      background: var(--vh-bg-elevated);
    }
  }

  [data-slot="attachment-action"]:active:not(:disabled) {
    background: var(--vh-bg-elevated);
  }

  [data-slot="attachment-action"]:focus-visible {
    outline: 3px solid color-mix(in oklab, var(--vh-highlighted) 25%, transparent);
  }

  [data-slot="attachment-action"]:disabled {
    cursor: not-allowed;
    opacity: 0.75;
  }

  [data-slot="attachment-trigger"] {
    background: transparent;
    border: 0;
    border-radius: inherit;
    cursor: pointer;
    inset: 0;
    padding: 0;
    position: absolute;
    z-index: 10;
  }

  [data-slot="attachment-group"] {
    display: flex;
    gap: 0.75rem;
    min-width: 0;
    overflow-x: auto;
    overscroll-behavior-x: contain;
    padding-block: 0.25rem;
    scroll-padding-inline: 0.25rem;
    scroll-snap-type: x mandatory;
    scrollbar-width: none;
  }

  [data-slot="attachment-group"] > [data-slot="attachment"] {
    flex: none;
    scroll-snap-align: start;
  }
}

export { default as Attachment } from "./Attachment.vue";
export { default as AttachmentAction } from "./AttachmentAction.vue";
export { default as AttachmentActions } from "./AttachmentActions.vue";
export { default as AttachmentContent } from "./AttachmentContent.vue";
export { default as AttachmentDescription } from "./AttachmentDescription.vue";
export { default as AttachmentGroup } from "./AttachmentGroup.vue";
export { default as AttachmentMedia } from "./AttachmentMedia.vue";
export { default as AttachmentTitle } from "./AttachmentTitle.vue";
export { default as AttachmentTrigger } from "./AttachmentTrigger.vue";
export type * from "./types.ts";

export type AttachmentStatus = "idle" | "uploading" | "processing" | "error" | "done";
export type AttachmentSize = "xs" | "sm" | "md";
export type AttachmentOrientation = "horizontal" | "vertical";
export type AttachmentMediaKind = "icon" | "image";

export interface AttachmentProps {
  /** Where the file is: `idle` before an upload, `uploading`, `processing`, `done`, or `error`. */
  status?: AttachmentStatus;
  size?: AttachmentSize;
  /** `vertical` puts the media above the name, as a tile. */
  orientation?: AttachmentOrientation;
}

export interface AttachmentSlots {
  /** `AttachmentMedia`, `AttachmentContent`, `AttachmentActions`, and an optional `AttachmentTrigger`. */
  default?: () => unknown;
}

export interface AttachmentMediaProps {
  /** `image` shows a picture that fills the square, `icon` an icon in the middle of it. */
  kind?: AttachmentMediaKind;
}

export interface AttachmentMediaSlots {
  default?: () => unknown;
}

export interface AttachmentActionProps {
  /** The accessible name of the button. */
  label?: string;
  disabled?: boolean;
}

export interface AttachmentActionSlots {
  /** The icon. Default: an X. */
  default?: () => unknown;
}

export interface AttachmentTriggerSlots {
  default?: () => unknown;
  /**
   * Renders the trigger as another element, such as a link to the file. Bind `props` to it, which holds the
   * `data-slot`, and render `children` inside it.
   */
  render?: (scope: { props: Record<string, unknown>; children: () => unknown }) => unknown;
}
